+import assert from "node:assert/strict";
+import { execFileSync } from "node:child_process";
+import { fileURLToPath } from "node:url";
+
+const reportCli = fileURLToPath(new URL("../bin/report.js", import.meta.url));
+
+test("renders the text report by default", () => {
+  const output = execFileSync(process.execPath, [reportCli], { encoding: "utf8" });
+
+  assert.equal(output, "items: 0\n");
+});
+
+test("renders a JSON report with --json", () => {
+  const output = execFileSync(process.execPath, [reportCli, "--json"], { encoding: "utf8" });
+
+  assert.deepEqual(JSON.parse(output), { report: "items: 0" });
+});
